// node_modules/@quartz-community/utils/dist/lang.js
function classNames(...classes) {
  return classes.filter(Boolean).join(" ");
}

// src/components/styles/graph.scss
var graph_default = ".graph > .graph-heading {\n  display: flex;\n  justify-content: space-between;\n  gap: 1rem;\n  align-items: flex-end;\n}\n.graph > .graph-heading h3 {\n  font-size: 1rem;\n  margin: 0;\n}\n.graph > .graph-heading .graph-eyebrow {\n  margin: 0 0 0.15rem;\n  color: var(--secondary);\n  font-size: 0.62rem;\n  font-weight: 750;\n  letter-spacing: 0.11em;\n}\n.graph > .graph-heading .graph-filter-count {\n  color: var(--gray);\n  font-size: 0.7rem;\n}\n.graph > .graph-filters {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 0.4rem;\n  margin: 0.65rem 0 0.45rem;\n}\n.graph > .graph-filters label {\n  display: flex;\n  flex-direction: column;\n  gap: 0.15rem;\n  color: var(--gray);\n  font-size: 0.62rem;\n  font-weight: 700;\n  letter-spacing: 0.04em;\n  text-transform: uppercase;\n}\n.graph > .graph-filters select {\n  width: 100%;\n  padding: 0.38rem 1.6rem 0.38rem 0.45rem;\n  border: 1px solid var(--lightgray);\n  border-radius: 7px;\n  background: var(--light);\n  color: var(--darkgray);\n  font: inherit;\n  font-size: 0.72rem;\n  font-weight: 650;\n  letter-spacing: 0;\n  text-transform: none;\n}\n.graph > .graph-outer {\n  border-radius: 5px;\n  border: 1px solid var(--lightgray);\n  box-sizing: border-box;\n  height: 250px;\n  margin: 0.3em 0 0;\n  position: relative;\n  overflow: hidden;\n}\n.graph > .graph-outer > .global-graph-icon {\n  cursor: pointer;\n  background: none;\n  border: none;\n  color: var(--dark);\n  opacity: 0.5;\n  width: 24px;\n  height: 24px;\n  position: absolute;\n  padding: 0.2rem;\n  margin: 0.3rem;\n  top: 0;\n  right: 0;\n  border-radius: 4px;\n  background-color: transparent;\n  transition: background-color 0.5s ease;\n}\n.graph > .graph-outer > .global-graph-icon:hover {\n  background-color: var(--lightgray);\n}\n.graph > .global-graph-outer {\n  position: fixed;\n  z-index: 9999;\n  left: 0;\n  top: 0;\n  width: 100vw;\n  height: 100%;\n  backdrop-filter: blur(4px);\n  display: none;\n  overflow: hidden;\n}\n.graph > .global-graph-outer.active {\n  display: inline-block;\n}\n.graph > .global-graph-outer > .global-graph-container {\n  border: 1px solid var(--lightgray);\n  background-color: var(--light);\n  border-radius: 5px;\n  box-sizing: border-box;\n  position: fixed;\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%);\n  height: 80vh;\n  width: 80vw;\n}\n@media all and (max-width: 800px) {\n  .graph > .global-graph-outer > .global-graph-container {\n    width: 90%;\n  }\n}\n\n.graph-container {\n  width: 100%;\n  height: 100%;\n}";

